(()=>{
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=value=>'₹'+Number(value).toLocaleString('en-IN');
const arrangements={'same-level':'Return at the same fuel level','included':'Included','customer-pays':'Customer pays for fuel','at-actuals':'Payable at actual cost'};
const fields=[['baseFare','Base rental fare · ₹'],['deliveryFee','Delivery / collection · ₹'],['driverAllowance','Driver allowance · ₹'],['taxAmount','Tax included in total · ₹'],['deposit','Refundable deposit · ₹'],['includedKm','Included kilometres · whole trip'],['includedHours','Included hours · whole trip'],['extraKmRate','Extra kilometre · ₹ / km'],['extraHourRate','Extra hour · ₹ / hour']];
const parse=row=>{try{return row.quote_details?JSON.parse(row.quote_details):null;}catch{return null;}};
const rowItem=(label,value)=>`<div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`;
window.GoRideBooking={
schedule:row=>`${esc(row.start_date)} ${esc(row.pickup_time||'(time to confirm)')} to ${esc(row.end_date)} ${esc(row.return_time||'(time to confirm)')} · IST`,
trip:row=>`<dl class="trip-points">${rowItem('Pick-up',row.pickup_address||'Meeting point to confirm')}${rowItem('Return',row.return_address||'Meeting point to confirm')}${row.trip_notes?rowItem('Trip notes',row.trip_notes):''}</dl>`,
quote:row=>{const q=parse(row);if(!q)return '';return `<section class="rental-quote" aria-label="Agreed rental quote"><div class="quote-heading"><h3>Agreed rental quote</h3><strong>${money(q.total)}</strong></div><dl class="quote-breakdown">${rowItem('Base fare',money(q.baseFare))}${rowItem('Delivery / collection',money(q.deliveryFee))}${rowItem('Driver allowance',money(q.driverAllowance))}${rowItem('Tax',money(q.taxAmount))}${rowItem('Refundable deposit · separate',money(q.deposit))}${rowItem('Rental + refundable deposit',money(q.total+q.deposit))}${rowItem('Included distance',q.includedKm+' km · whole trip')}${rowItem('Included time',q.includedHours+' hours · whole trip')}${rowItem('Extra distance',money(q.extraKmRate)+' / km')}${rowItem('Extra time',money(q.extraHourRate)+' / hour')}${rowItem('Fuel',arrangements[q.fuel]||q.fuel)}${rowItem('Tolls & parking',arrangements[q.tollsParking]||q.tollsParking)}${rowItem('Interstate permits',arrangements[q.permits]||q.permits)}</dl><p>Payment is not collected here. Variable charges apply only as agreed for your trip; the deposit is separate from the rental fare.</p></section>`;},
quoteFields:row=>{
const existing=parse(row)||{},duration=Math.max(1,Math.ceil((Date.parse(row.end_date+'T'+(row.return_time||'00:00')+':00+05:30')-Date.parse(row.start_date+'T'+(row.pickup_time||'00:00')+':00+05:30'))/3600000));
return `<p class="booking-help">Complete the whole-trip quote in rupees. Discuss it with the customer before accepting. Payment is not collected here.</p><div class="account-grid quote-editor">${fields.map(([key,label])=>`<label>${label}<input type="number" name="${key}" step="1" min="${key==='includedHours'?1:0}" max="10000000" required value="${esc(existing[key]??(key==='deposit'?(row.mode==='self'?3000:0):key==='includedHours'?duration:key==='includedKm'||key==='baseFare'?'':0))}"></label>`).join('')}<label>Fuel<select name="fuel" required><option value="">Choose fuel arrangement</option><option value="same-level">Return at same level</option><option value="included">Included in fare</option><option value="customer-pays">Customer pays</option></select></label><label>Tolls &amp; parking<select name="tollsParking" required><option value="">Choose arrangement</option><option value="included">Included in fare</option><option value="at-actuals">Payable at actual cost</option></select></label><label>Interstate permits<select name="permits" required><option value="">Choose arrangement</option><option value="included">Included / not required</option><option value="at-actuals">Payable at actual cost</option></select></label></div><p class="quote-total" aria-live="polite">Rental total: <strong id="quote-total">₹0</strong><br><small>Refundable deposit is separate.</small></p><label class="consent"><input type="checkbox" name="quoteAgreed" required><span>I have explained and agreed this quote, meeting points and timings with the customer.</span></label>`;
},
readQuote:form=>{const data=Object.fromEntries(new FormData(form)),quoteDetails={};for(const [key] of fields)quoteDetails[key]=Number(data[key]);for(const key of ['fuel','tollsParking','permits'])quoteDetails[key]=data[key];return {quoteDetails,quotedTotal:quoteDetails.baseFare+quoteDetails.deliveryFee+quoteDetails.driverAllowance+quoteDetails.taxAmount};}
};
document.addEventListener('input',event=>{const form=event.target.closest('#decision-form');if(!form||!document.getElementById('quote-total'))return;const total=window.GoRideBooking.readQuote(form).quotedTotal;document.getElementById('quote-total').textContent=Number.isFinite(total)?money(total):'Check amounts';});
})();
